// Compile shipped HLSL during the Windows build, never on voice activation.
// The source text, entry points, source name and compiler flags are identical
// to the original runtime compiler. Generated files stay in Cargo OUT_DIR.
#[cfg(windows)]
#[allow(dead_code)]
#[path = "src/material_config.rs"]
mod material_config;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    for name in ["material_config.rs", "glass.hlsl", "configured_material.hlsl",
        "liquid.hlsl", "voice_content.hlsl", "adaptive.hlsl"] {
        println!("cargo:rerun-if-changed=src/{name}");
    }
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return; // Portable model tests do not compile or load Windows shaders.
    }
    #[cfg(windows)]
    compile_windows_shaders();
    #[cfg(not(windows))]
    panic!("Windows glass bytecode must be built on a Windows host; no runtime-compilation fallback is generated");
}

#[cfg(windows)]
fn compile_windows_shaders() {
    use std::{ffi::CString, fmt::Write as _, fs, path::PathBuf, slice};
    use windows::{core::{s, PCSTR}, Win32::Graphics::Direct3D::{ID3DBlob, Fxc::D3DCompile}};
    let out = PathBuf::from(std::env::var_os("OUT_DIR").expect("Cargo OUT_DIR missing"));
    let glass = include_str!("src/glass.hlsl");
    let liquid = include_str!("src/liquid.hlsl");
    let voice = include_str!("src/voice_content.hlsl");
    let groups: Vec<(&str, String, Vec<(&str, &str)>)> = vec![
        ("configured", format!("{}\n{}\n{}", material_config::hlsl_header().expect("Invalid material configuration"),
            glass, include_str!("src/configured_material.hlsl")),
            vec![("fullscreen_vs", "vs_5_0"), ("convert_ps", "ps_5_0"),
                ("blur_ps", "ps_5_0"), ("configured_material_ps", "ps_5_0")]),
        ("optical", format!("{}\n{}", glass, liquid),
            vec![("liquid_material_ps", "ps_5_0"), ("liquid_adapt_ps", "ps_5_0")]),
        ("voice", format!("#define LIQUID_VOICE_CONTENT 1\n{}\n{}\n{}", glass, voice, liquid),
            vec![("liquid_material_ps", "ps_5_0")]),
        ("adaptive", format!("#define LIQUID_VOICE_CONTENT 1\n{}\n{}\n{}\n{}", glass, voice, liquid,
            include_str!("src/adaptive.hlsl")),
            vec![("adaptive_material_ps", "ps_5_0"), ("adaptive_reduce_ps", "ps_5_0")]),
    ];
    let mut table = String::from("// Generated by build.rs; exact-source lookup, not an entry-name-only cache.\nconst ENTRIES: &[EmbeddedShader] = &[\n");
    let mut manifest = String::from("source_name=glass-live.hlsl flags1=32768 flags2=0\n");
    let mut count = 0;
    for (group, source, entries) in groups {
        fs::write(out.join(format!("{group}.hlsl")), source.as_bytes()).expect("Cannot write shader source evidence");
        for (entry, target) in entries {
            let entry_c = CString::new(entry).unwrap();
            let target_c = CString::new(target).unwrap();
            let mut code = None;
            let mut errors: Option<ID3DBlob> = None;
            let result = unsafe {
                D3DCompile(source.as_ptr().cast(), source.len(), s!("glass-live.hlsl"), None, None,
                    PCSTR(entry_c.as_ptr().cast()), PCSTR(target_c.as_ptr().cast()),
                    1 << 15, 0, &mut code, Some(&mut errors))
            };
            if let Err(error) = result {
                let detail = errors.map(|b| unsafe {
                    String::from_utf8_lossy(slice::from_raw_parts(b.GetBufferPointer().cast(), b.GetBufferSize())).into_owned()
                }).unwrap_or_default();
                panic!("Build-time HLSL compilation failed: {group}/{entry}/{target}: {error}; {detail}");
            }
            let code = code.expect("Compiler returned no bytecode");
            let bytes = unsafe { slice::from_raw_parts(code.GetBufferPointer().cast::<u8>(), code.GetBufferSize()) };
            assert!(bytes.starts_with(b"DXBC"), "Unexpected shader bytecode container");
            let binary = format!("{group}-{entry}.cso");
            fs::write(out.join(&binary), bytes).expect("Cannot write compiled shader");
            writeln!(table, "    EmbeddedShader {{ source: include_str!(concat!(env!(\"OUT_DIR\"), \"/{group}.hlsl\")), entry: b\"{entry}\", target: b\"{target}\", code: include_bytes!(concat!(env!(\"OUT_DIR\"), \"/{binary}\")) }},").unwrap();
            writeln!(manifest, "{group} {entry} {target} bytes={}", bytes.len()).unwrap();
            count += 1;
        }
    }
    assert_eq!(count, 9, "Shipped constructor entry set changed");
    table.push_str("];\n");
    fs::write(out.join("embedded_shader_table.rs"), table).expect("Cannot write embedded table");
    fs::write(out.join("embedded_shader_manifest.txt"), manifest).expect("Cannot write shader manifest");
}
